$owners=sb('GET','municipal_owner_records?select=id&limit=5000');$enrich=sb('GET','owner_enrichment_queue?select=id,priority_score,owner_name,property_address&order=priority_score.desc&limit=50');$comp=sb('GET','owner_compliance_reviews?select=id&limit=50');$approved=sb('GET','approved_owner_contact_queue?select=id,owner_name,property_address,priority_score&order=priority_score.desc&limit=20');$streets=sb('GET','street_intelligence?select=street_name,town,street_score,jessica_notes&order=street_score.desc&limit=10');$leads=sb('GET','leads?select=id,name,address&order=created_at.desc&limit=10');$topStreet=$streets['data'][0]??null;$topOpp=$approved['data'][0]??($enrich['data'][0]??null);$priorities=[];if($topOpp)$priorities[]='Review top owner opportunity: '.($topOpp['owner_name']??'Unknown').' — '.($topOpp['property_address']??'');if($topStreet)$priorities[]='Focus Hunter research on '.$topStreet['street_name'].' in '.$topStreet['town'];if(!empty($leads['data']))$priorities[]='Review new lead activity and call Mark-priority leads first.';$summary="Good Morning Mark.\n\nJessica Hunter OS is online.\n\nMunicipal owners reviewed: ".count($owners['data'])."\nResearch queue: ".count($enrich['data'])."\nCompliance reviews: ".count($comp['data'])."\nApproved contact queue: ".count($approved['data'])."\nTop street: ".($topStreet?($topStreet['street_name'].' — score '.$topStreet['street_score']):'Not enough street data yet')."\n\nRecommended action: ".($priorities[0]??'Run Hunter Pipeline and review results.');$payload=['brief_date'=>date('Y-m-d'),'brief_type'=>'morning','title'=>'Jessica Morning Brief — '.date('M j, Y'),'summary'=>$summary,'priorities'=>$priorities,'raw_metrics'=>['owners'=>count($owners['data']),'research_queue'=>count($enrich['data']),'compliance_reviews'=>count($comp['data']),'approved_queue'=>count($approved['data']),'top_street'=>$topStreet,'top_opportunity'=>$topOpp],'created_at'=>date('c')];$r=sb('POST','jessica_briefs',[$payload]);echo json_encode([